#!/usr/bin/env python3
"""The factory's job commands for this repo: python3 .factory/factory.py --help (generated by `factory render`)."""
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE / "lib"))
from ajantrik_core.cli import main  # noqa: E402

sys.exit(main(sys.argv[1:], root=HERE.parent))
